class PI:
    def __init__(self, kp, ki): self.kp, self.ki, self.acc = kp, ki, 0.0
    def step(self, setpoint, measured):
        err = setpoint - measured
        self.acc = max(-100, min(100, self.acc + err))   # anti-windup clamp
        return self.kp * err + self.ki * self.acc

